10	/// The `entries` Hive box's name — the first `hive_ce` box in the app
11	/// (Code Map). A raw `Box<Map>`, not a generated `HiveObject`/
12	/// `TypeAdapter` (Design Notes: avoids adapter codegen) — spec-4-1's
13	/// `EntriesRepositoryImpl.list()` is this box's first reader
14	/// (`create()`'s own writes were, until then, never read back by
15	/// anything).
16	const entriesBoxName = 'entries';
17	
18	/// Registers the `entries` feature into the project's single `get_it`
19	/// instance (`sl`) — mirrors `features/account/account_injection.dart`'s
20	/// pattern. Called from `setupCoreDependencies()` right after
21	/// `Hive.initFlutter()` (Code Map), which must already have run by the
22	/// time this opens its box.
23	Future<void> registerEntriesFeature() async {
24	  final entriesBox = await Hive.openBox<Map>(entriesBoxName);
25	  sl.registerSingleton<Box<Map>>(entriesBox);
26	
27	  sl.registerLazySingleton<EntriesRemoteDataSource>(
28	    () => EntriesRemoteDataSource(sl<ApiClient>()),
29	  );
30	
31	  sl.registerLazySingleton<EntriesRepository>(
32	    () => EntriesRepositoryImpl(
33	      remoteDataSource: sl<EntriesRemoteDataSource>(),
34	      entriesBox: sl<Box<Map>>(),
35	    ),
36	  );
37	
38	  // spec-4-1 — `MeusRegistrosCubit` is a `lazySingleton`, not a factory
39	  // (Code Map/Boundaries), like `AccountSettingsCubit`: long-lived, so
40	  // `dispose:` wires its `close()` into `get_it`'s own reset lifecycle,
41	  // same convention `account_injection.dart` already uses.
42	  sl.registerLazySingleton<MeusRegistrosCubit>(
43	    () => MeusRegistrosCubit(sl<EntriesRepository>()),
44	    dispose: (cubit) => cubit.close(),
45	  );
46	}
