74	bool _listEquals(List<Entry> a, List<Entry> b) {
75	  if (a.length != b.length) {
76	    return false;
77	  }
78	  for (var i = 0; i < a.length; i++) {
79	    if (a[i] != b[i]) {
80	      return false;
81	    }
82	  }
83	  return true;
84	}
