306	/// "Hoje"/"Ontem"/`dd/mm/yyyy` — presentation's own job (Code Map: day
307	/// labels aren't the pure `groupEntriesByDate()`'s concern). [date] is
308	/// always already truncated to local midnight (`EntryDateGroup`'s own
309	/// contract).
310	String _dayLabel(DateTime date) {
311	  final now = DateTime.now();
312	  final today = DateTime(now.year, now.month, now.day);
313	  final yesterday = today.subtract(const Duration(days: 1));
314	  if (date == today) {
315	    return 'Hoje';
316	  }
317	  if (date == yesterday) {
318	    return 'Ontem';
319	  }
320	  final day = date.day.toString().padLeft(2, '0');
321	  final month = date.month.toString().padLeft(2, '0');
322	  return '$day/$month/${date.year}';
323	}
