113	/// Drives the Áudio tab's recording -> processing -> transcribed/error
114	/// pipeline (Intent). A fresh, `get_it`-factory-scoped instance per "+"
115	/// tap, same convention as `TextEntryCubit` — [MicRecorder]/
116	/// [AudioTranscriber] themselves stay long-lived `get_it` singletons
117	/// (`capture_injection.dart`), shared across every modal open the way
118	/// `EntriesRepository` already is for `TextEntryCubit`.
119	class AudioEntryCubit extends Cubit<AudioCaptureState> {
120	  AudioEntryCubit(this._micRecorder, this._audioTranscriber, this._repository)
121	    : super(const AudioIdle());
122	
123	  final MicRecorder _micRecorder;
124	  final AudioTranscriber _audioTranscriber;
125	  final EntriesRepository _repository;
126	
127	  Timer? _elapsedTimer;
128	
129	  /// Bumped by [cancel] so an in-flight [startRecording]/[stopRecording]
130	  /// continuation can tell "the user already left the Áudio tab while I
131	  /// was awaiting" apart from "nothing has changed since I started" —
132	  /// the same role `isClosed` already plays for `close()`, but for a tab
133	  /// switch that doesn't close the cubit itself (Review finding: without
134	  /// this, `cancel()` running mid-await either left the recorder running
135	  /// unobserved, or let a stale `stop()`/transcription result resurrect a
136	  /// flow the user already left).
137	  int _generation = 0;
138	
139	  /// Guards [stopRecording] against a second concurrent call (e.g. a fast
140	  /// double-tap on the stop control before the UI rebuilds past
141	  /// [AudioRecording]) — without this, a second `_micRecorder.stop()` call
142	  /// racing the first could return `null` (nothing left to stop) and
143	  /// overwrite a perfectly good [AudioProcessing]/transcription result
144	  /// with a bogus [AudioError] (Review finding).
145	  bool _stopping = false;
146	
147	  /// Forwarded straight from [MicRecorder.amplitudeStream] — lets
148	  /// `_AudioTab`'s waveform animate without ever importing `package:record`
149	  /// itself (Boundaries).
150	  Stream<double> get amplitudeStream => _micRecorder.amplitudeStream;
151	
152	  /// Starts recording — called from `InsertionModal`'s own
153	  /// `_AudioIdleView` the moment the user taps the idle mic button
154	  /// (correction: a previous pass called this automatically from the
155	  /// tab-switch listener instead), and again by [retry] when the last
156	  /// attempt failed before any file ever existed (permission
157	  /// denied). Ignored while a recording is already in progress, and —
158	  /// Review finding — ignored once the pipeline has moved past recording
159	  /// ([AudioProcessing]/[AudioTranscribed]/an [AudioError] that still
160	  /// carries a file): without this, re-entering the Áudio tab after a
161	  /// completed transcription silently discarded the transcribed text and
162	  /// started a brand-new recording over it. Only [AudioIdle] (fresh) or
163	  /// an [AudioError] with no file (nothing to discard) actually start.
164	  Future<void> startRecording() async {
165	    final current = state;
166	    final canStart =
167	        current is AudioIdle ||
168	        (current is AudioError && current.path == null);
169	    if (!canStart) {
170	      return;
171	    }
172	    final generation = ++_generation;
173	    bool hasPermission;
174	    try {
175	      hasPermission = await _micRecorder.hasPermission();
176	    } catch (_) {
177	      // Review finding: a thrown `PlatformException` (native-side error)
178	      // must never escape uncaught — surfaces through the same
179	      // error/retry path as a plain permission denial.
180	      if (isClosed || generation != _generation) {
181	        return;
182	      }
183	      emit(
184	        const AudioError(
185	          path: null,
186	          durationSeconds: null,
187	          message: 'Não foi possível acessar o microfone.',
188	        ),
189	      );
190	      return;
191	    }
192	    if (isClosed || generation != _generation) {
193	      return;
194	    }
195	    if (!hasPermission) {
196	      emit(
197	        const AudioError(
198	          path: null,
199	          durationSeconds: null,
200	          message:
201	              'Permissão de microfone negada. Toque em "Tentar novamente" '
202	              'para permitir o acesso.',
203	        ),
204	      );
205	      return;
206	    }
207	    try {
208	      await _micRecorder.start();
209	    } catch (_) {
210	      // Review finding: same rationale as the `hasPermission()` catch
211	      // above — a native-side start failure must surface through the
212	      // normal error/retry path instead of escaping uncaught.
213	      if (isClosed || generation != _generation) {
214	        // Review finding: the shared `_micRecorder` singleton may already
215	        // belong to a newer, currently-active generation by the time this
216	        // stale catch fires — never release it from here, only from the
217	        // generation that's still actually live, or this would silently
218	        // kill a different, active recording with no error surfaced.
219	        return;
220	      }
221	      // Also releases the native recorder best-effort (Review finding): a
222	      // partial/failed `start()` may still have left a session open.
223	      unawaited(_safeCancelRecorder());
224	      emit(
225	        const AudioError(
226	          path: null,
227	          durationSeconds: null,
228	          message: 'Não foi possível iniciar a gravação.',
229	        ),
230	      );
231	      return;
232	    }
233	    if (isClosed || generation != _generation) {
234	      // Review finding: `cancel()` bumped `_generation` (the user already
235	      // left the Áudio tab) while `start()` was in flight — stop/discard
236	      // the session we just started instead of leaving a live, unobserved
237	      // recording running.
238	      unawaited(_safeCancelRecorder());
239	      return;
240	    }
241	    _startElapsedTimer();
242	    emit(const AudioRecording(elapsedSeconds: 0));
243	  }
244	
245	  void _startElapsedTimer() {
246	    _elapsedTimer?.cancel();
247	    var elapsed = 0;
248	    _elapsedTimer = Timer.periodic(const Duration(seconds: 1), (_) {
249	      elapsed++;
250	      if (state is AudioRecording) {
251	        emit(AudioRecording(elapsedSeconds: elapsed));
252	      }
253	    });
254	  }
255	
256	  /// Stops recording and immediately kicks off transcription — the I/O
257	  /// matrix's "Happy path"/"Transcription fails" rows. Ignored outside
258	  /// [AudioRecording] (e.g. a stray second tap on the stop control) and
259	  /// — Review finding — ignored while a previous call is still awaiting
260	  /// `_micRecorder.stop()` ([_stopping]): without this, a fast double-tap
261	  /// on the stop control could fire a second `_micRecorder.stop()` call
262	  /// that returns `null` (nothing left to stop) and clobber the first
263	  /// call's genuine result with a bogus `AudioError`.
264	  Future<void> stopRecording() async {
265	    if (state is! AudioRecording || _stopping) {
266	      return;
267	    }
268	    _stopping = true;
269	    final generation = _generation;
270	    _elapsedTimer?.cancel();
271	    MicRecording? recording;
272	    try {
273	      recording = await _micRecorder.stop();
274	    } catch (_) {
275	      // Review finding: a thrown `PlatformException` must never escape
276	      // uncaught — surfaces through the normal error/retry path instead.
277	      _stopping = false;
278	      if (isClosed || generation != _generation) {
279	        // Review finding: the shared `_micRecorder` singleton may already
280	        // belong to a newer, currently-active generation by the time this
281	        // stale catch fires — never release it from here, only from the
282	        // generation that's still actually live, or this would silently
283	        // kill a different, active recording with no error surfaced.
284	        return;
285	      }
286	      // Also releases the native recorder best-effort (Review finding): a
287	      // failed `stop()` leaves the actual native session state
288	      // unconfirmed, so this is the only chance to try to release it.
289	      unawaited(_safeCancelRecorder());
290	      emit(
291	        const AudioError(
292	          path: null,
293	          durationSeconds: null,
294	          message: 'Não foi possível gravar o áudio.',
295	        ),
296	      );
297	      return;
298	    }
299	    _stopping = false;
300	    // Review finding: without the `_generation` check, a `cancel()` that
301	    // ran while `_micRecorder.stop()` was in flight (tab switch right
302	    // after tapping stop) already reset the cubit to `AudioIdle` — this
303	    // continuation must not resurrect the flow with a stale
304	    // `AudioProcessing`/`AudioError` emission on top of that reset.
305	    if (isClosed || generation != _generation) {
306	      return;
307	    }
308	    if (recording == null) {
309	      // Stopped with nothing actually captured — the I/O matrix has no
310	      // dedicated row for this (it should be unreachable in practice: the
311	      // recorder was just started above), but `AudioError` with no file
312	      // still gives the user a path back in via retry's permission-
313	      // re-request branch rather than leaving the cubit stuck mid-flow.
314	      emit(
315	        const AudioError(
316	          path: null,
317	          durationSeconds: null,
318	          message: 'Não foi possível gravar o áudio.',
319	        ),
320	      );
321	      return;
322	    }
323	    emit(
324	      AudioProcessing(
325	        path: recording.path,
326	        durationSeconds: recording.durationSeconds,
327	      ),
328	    );
329	    await _transcribe(recording.path, recording.durationSeconds);
330	  }
331	
332	  Future<void> _transcribe(String path, int durationSeconds) async {
333	    final text = await _audioTranscriber.transcribe(path);
334	    if (isClosed) {
335	      return;
336	    }
337	    // Guards a tab switch away mid-processing (`cancel()`, below) that
338	    // already reset the state to `AudioIdle` by the time this resolves —
339	    // without this, the eventual transcription result would still land
340	    // and resurrect a flow the user already left.
341	    if (state is! AudioProcessing ||
342	        (state as AudioProcessing).path != path) {
343	      return;
344	    }
345	    if (text == null) {
346	      emit(
347	        AudioError(
348	          path: path,
349	          durationSeconds: durationSeconds,
350	          message: 'Não foi possível transcrever o áudio.',
351	        ),
352	      );
353	      return;
354	    }
355	    emit(
356	      AudioTranscribed(
357	        path: path,
358	        durationSeconds: durationSeconds,
359	        text: text,
360	        saving: false,
361	      ),
362	    );
363	  }
364	
365	  /// "Tentar novamente" — re-requests permission when no file was ever
366	  /// recorded, or re-transcribes the same preserved file otherwise (I/O
367	  /// matrix: never re-records, never auto-retries on its own). A no-op
368	  /// outside [AudioError], or for a save failure (non-null [AudioError.
369	  /// text]) — that case's own retry is just tapping Salvar again, handled
370	  /// by [save] directly, not this method.
371	  Future<void> retry() async {
372	    final current = state;
373	    if (current is! AudioError || current.text != null) {
374	      return;
375	    }
376	    final path = current.path;
377	    final durationSeconds = current.durationSeconds;
378	    if (path == null || durationSeconds == null) {
379	      await startRecording();
380	      return;
381	    }
382	    emit(AudioProcessing(path: path, durationSeconds: durationSeconds));
383	    await _transcribe(path, durationSeconds);
384	  }
385	
386	  /// Mirrors the Texto field's own `updateText` — keeps the transcribed
387	  /// text editable before Salvar (Acceptance Criteria). Ignored while a
388	  /// save is already in flight, same rationale as `TextEntryCubit.
389	  /// updateText`.
390	  void updateText(String text) {
391	    final current = state;
392	    if (current is AudioTranscribed && !current.saving) {
393	      emit(current.copyWith(text: text));
394	    } else if (current is AudioError && current.text != null) {
395	      // Review finding: a save failure (`AudioError` with non-null
396	      // `text`) renders the same editable field as `AudioTranscribed`
397	      // (`_AudioErrorView`'s non-retry branch) — without this branch,
398	      // typing there updated the `TextField`'s own controller visually
399	      // but never the cubit's record of the text, so a retried `save()`
400	      // would silently resend the stale pre-failure text.
401	      emit(
402	        AudioError(
403	          path: current.path,
404	          durationSeconds: current.durationSeconds,
405	          message: current.message,
406	          text: text,
407	        ),
408	      );
409	    }
410	  }
411	
412	  /// Called when the Áudio tab loses focus mid-recording/mid-processing
413	  /// (`InsertionModal`'s tab-switch listener) — the I/O matrix's "Leave
414	  /// tab mid-recording" row: stops/releases the recorder, no `create()`
415	  /// ever fires. A no-op for every other state when [discardPreserved] is
416	  /// `false` (the default) — in particular [AudioTranscribed]/[AudioError],
417	  /// where the Never clause's trivial scope (resource safety only, not
418	  /// full Story 3.4 cancel-safety) means a tab switch must preserve the
419	  /// result rather than discard it.
420	  ///
421	  /// [discardPreserved] — Review finding: `InsertionModal.show()`'s
422	  /// `finally` also calls this (before `close()`) when the *whole modal*
423	  /// is dismissed (✕/swipe-down/barrier tap), not just the tab. In that
424	  /// case there's no "switch back to the tab later" to preserve for —
425	  /// the cubit is about to be closed — so a preserved [AudioTranscribed]
426	  /// or file-carrying [AudioError]'s temp file would otherwise never be
427	  /// cleaned up and leak on disk forever. Pass `true` only from that
428	  /// call site.
429	  Future<void> cancel({bool discardPreserved = false}) async {
430	    // Bumped unconditionally — including when the state below doesn't
431	    // match either branch — so an in-flight `startRecording()`/
432	    // `stopRecording()` continuation still sees the mismatch and aborts
433	    // itself (Review finding: previously only invalidated a flow already
434	    // visible in `state`, missing the window while those methods were
435	    // still awaiting).
436	    _generation++;
437	    // Review finding: without this, a hung `_micRecorder.stop()` call
438	    // (one that never resolves) left `_stopping` stuck `true` forever —
439	    // `stopRecording()`'s own guard made it a permanent no-op for the
440	    // rest of this cubit's life. The `_generation` bump above already
441	    // makes that stale continuation's eventual result a no-op, so
442	    // resetting this eagerly is always safe, mirroring `PhotoEntryCubit.
443	    // cancel()`'s own `_picking = false` reset.
444	    _stopping = false;
445	    final current = state;
446	    if (current is AudioRecording) {
447	      _elapsedTimer?.cancel();
448	      await _safeCancelRecorder();
449	      if (isClosed) {
450	        return;
451	      }
452	      emit(const AudioIdle());
453	    } else if (current is AudioProcessing) {
454	      // The recorder itself is already stopped by the time this state is
455	      // reached (`stopRecording` stops it before emitting `AudioProcessing`)
456	      // — only resetting the cubit's own state is left, so the pending
457	      // `_transcribe` continuation's own `state is! AudioProcessing` guard
458	      // (above) drops its result instead of resurrecting this flow. Review
459	      // finding: the already-recorded file is abandoned for good at this
460	      // point (nothing will ever retry it), so it must be deleted here —
461	      // the other orphan-file case `_micRecorder.cancel()` above already
462	      // handles on its own.
463	      unawaited(_deleteRecordingFile(current.path));
464	      emit(const AudioIdle());
465	    } else if (discardPreserved) {
466	      final path = switch (current) {
467	        AudioTranscribed(path: final p) => p,
468	        AudioError(path: final p) => p,
469	        _ => null,
470	      };
471	      if (path != null) {
472	        unawaited(_deleteRecordingFile(path));
473	      }
474	    }
475	  }
476	
477	  /// Best-effort `_micRecorder.cancel()` — a thrown `PlatformException`
478	  /// here (Review finding) must never escape uncaught, since both call
479	  /// sites (above, and [startRecording]'s own abandon-on-generation-
480	  /// mismatch branch) call this fire-and-forget.
481	  Future<void> _safeCancelRecorder() async {
482	    try {
483	      await _micRecorder.cancel();
484	    } catch (_) {
485	      // Best-effort — nothing in the UI depends on this succeeding.
486	    }
487	  }
488	
489	  /// I/O matrix's "Happy path"/"Save fails" rows: fires `POST /entries`
490	  /// with `source: audio` and `mediaDurationSeconds` for the current
491	  /// transcribed text. Mirrors `TextEntryCubit.save()`'s `isClosed`/
492	  /// no-double-submit guards exactly (Boundaries).
493	  ///
494	  /// Review finding: also callable from an [AudioError] save failure
495	  /// (non-null [AudioError.text]) — `_AudioErrorView`'s non-retry branch
496	  /// re-renders the editable field and calls this same method for its
497	  /// "Salvar" button, but the original guard only matched
498	  /// [AudioTranscribed], making a retry after any save failure a
499	  /// permanent no-op.
500	  Future<void> save() async {
501	    final current = state;
502	    final String path;
503	    final int durationSeconds;
504	    final String text;
505	    if (current is AudioTranscribed && !current.saving) {
506	      path = current.path;
507	      durationSeconds = current.durationSeconds;
508	      text = current.text.trim();
509	    } else if (current is AudioError &&
510	        current.text != null &&
511	        current.path != null &&
512	        current.durationSeconds != null) {
513	      path = current.path!;
514	      durationSeconds = current.durationSeconds!;
515	      text = current.text!.trim();
516	    } else {
517	      return;
518	    }
519	    if (text.isEmpty) {
520	      return;
521	    }
522	    emit(
523	      AudioTranscribed(
524	        path: path,
525	        durationSeconds: durationSeconds,
526	        text: text,
527	        saving: true,
528	      ),
529	    );
530	    final result = await _repository.create(
531	      content: text,
532	      source: EntrySource.audio,
533	      mediaDurationSeconds: durationSeconds,
534	    );
535	    // Mirrors `TextEntryCubit.save()`'s own `isClosed` guard — this
536	    // cubit's `close()` can race the awaited call above (e.g. the modal's
537	    // barrier is dismissed mid-save).
538	    if (isClosed) {
539	      return;
540	    }
541	    result.match(
542	      (failure) => emit(
543	        AudioError(
544	          path: path,
545	          durationSeconds: durationSeconds,
546	          message: failure.message,
547	          text: text,
548	        ),
549	      ),
550	      (_) {
551	        // Review finding: the recorded temp file was never deleted after
552	        // a successful save — fire-and-forget, a deletion failure must
553	        // never block the modal from closing.
554	        unawaited(_deleteRecordingFile(path));
555	        emit(const AudioSaved());
556	      },
557	    );
558	  }
559	
560	  /// Best-effort cleanup for a temp recording file this cubit is done
561	  /// with (saved successfully, or abandoned for good by [cancel] mid-
562	  /// processing) — deletion failures are swallowed since nothing in the
563	  /// UI depends on this succeeding (Review finding: previously never
564	  /// called at all, leaking a `.wav` file per recording indefinitely).
565	  Future<void> _deleteRecordingFile(String path) async {
566	    try {
567	      await File(path).delete();
568	    } catch (_) {
569	      // Best-effort — a missing/already-deleted file, or a transient
570	      // disk error, is never worth surfacing to the user.
571	    }
572	  }
573	
574	  @override
575	  Future<void> close() {
576	    _elapsedTimer?.cancel();
577	    return super.close();
578	  }
579	}
