24	/// A plain (non-mocktail) fake — this cubit's own tests need a scriptable
25	/// `list()` result per call (first page vs. a later `loadMore()` page),
26	/// which a single static mocktail stub can't express as naturally.
27	class _FakeEntriesRepository implements EntriesRepository {
28	  final List<Either<Failure, EntriesPage>> _listResults = [];
29	  final List<({String? cursor, int limit})> listCalls = [];
30	
31	  /// Queues the next `list()` call's result, in order.
32	  void queueList(Either<Failure, EntriesPage> result) {
33	    _listResults.add(result);
34	  }
35	
36	  @override
37	  Future<Either<Failure, Entry>> create({
38	    required String content,
39	    required EntrySource source,
40	    int? mediaDurationSeconds,
41	  }) async => throw UnimplementedError('not expected to be called');
42	
43	  @override
44	  Future<Either<Failure, EntriesPage>> list({
45	    String? cursor,
46	    int limit = 20,
47	  }) async {
48	    listCalls.add((cursor: cursor, limit: limit));
49	    if (_listResults.isEmpty) {
50	      throw StateError('no queued list() result for call #${listCalls.length}');
51	    }
52	    return _listResults.removeAt(0);
53	  }
54	}
