56	/// A `Completer`-per-call fake, letting a test resolve `list()` calls in
57	/// whatever order it chooses — needed to reproduce the stale-result race
58	/// (review finding): an older call's result landing after a newer call has
59	/// already changed the state.
60	class _GatedEntriesRepository implements EntriesRepository {
61	  final List<Completer<Either<Failure, EntriesPage>>> _completers = [];
62	
63	  void resolve(int callIndex, Either<Failure, EntriesPage> result) {
64	    _completers[callIndex].complete(result);
65	  }
66	
67	  @override
68	  Future<Either<Failure, Entry>> create({
69	    required String content,
70	    required EntrySource source,
71	    int? mediaDurationSeconds,
72	  }) async => throw UnimplementedError('not expected to be called');
73	
74	  @override
75	  Future<Either<Failure, EntriesPage>> list({
76	    String? cursor,
77	    int limit = 20,
78	  }) {
79	    final completer = Completer<Either<Failure, EntriesPage>>();
80	    _completers.add(completer);
81	    return completer.future;
82	  }
83	}
