61	/// A plain (non-mocktail) fake — queues one `list()` result per call, same
62	/// rationale as `meus_registros_cubit_test.dart`'s own fake, plus an
63	/// optional [firstCallGate] so a test can hold the very first `list()`
64	/// call unresolved to observe the skeleton's 300ms threshold.
65	class _FakeEntriesRepository implements EntriesRepository {
66	  final List<Either<Failure, EntriesPage>> _listResults = [];
67	  int listCallCount = 0;
68	  Completer<void>? firstCallGate;
69	
70	  void queueList(Either<Failure, EntriesPage> result) {
71	    _listResults.add(result);
72	  }
73	
74	  @override
75	  Future<Either<Failure, Entry>> create({
76	    required String content,
77	    required EntrySource source,
78	    int? mediaDurationSeconds,
79	  }) async => throw UnimplementedError('not expected to be called');
80	
81	  @override
82	  Future<Either<Failure, EntriesPage>> list({
83	    String? cursor,
84	    int limit = 20,
85	  }) async {
86	    listCallCount++;
87	    if (listCallCount == 1 && firstCallGate != null) {
88	      await firstCallGate!.future;
89	    }
90	    if (_listResults.isEmpty) {
91	      throw StateError('no queued list() result for call #$listCallCount');
92	    }
93	    return _listResults.removeAt(0);
94	  }
95	}
