87	/// `capture_flow_e2e_test.dart` already proves for `create()`. Driven
88	/// directly against `MeusRegistrosCubit`'s own public API
89	/// (`loadFirstPage`/`loadMore`), the exact `lazySingleton` instance
90	/// `MeusRegistrosScreen` resolves through `sl`, wired to the real
91	/// `EntriesRepositoryImpl` -> `EntriesRemoteDataSource` -> `ApiClient` ->
92	/// `Dio` (both real interceptors attached) -> a real `entries` Hive box.
93	///
94	/// This complements rather than duplicates existing coverage:
95	/// `meus_registros_cubit_test.dart`/`meus_registros_screen_test.dart`
96	/// already prove the state machine/UI against a fake `EntriesRepository`,
97	/// and `entries_repository_impl_test.dart` already proves
98	/// `list()`/`_offlineFallback()` against a mocked datasource/`Box`. None
99	/// of them drives the real cubit through the real network + real disk
100	/// pipeline together, including a genuine retry-then-fallback sequence,
101	/// the way the app actually does on opening "Meus Registros" — a gap
102	/// `deferred-work.md` names explicitly for spec-4-1.
103	///
104	/// Like `capture_flow_e2e_test.dart`, this uses a plain `test()` driving
105	/// the cubit directly rather than `tester.tap`/`pumpAndSettle`: these
106	/// awaits are genuine async I/O (real Dio round trips, including the
107	/// retry interceptor's real 500ms delay in the offline-fallback case), and
108	/// `pumpAndSettle()` only waits for scheduled frames under the fake-async
109	/// test clock.
110	void main() {
111	  TestWidgetsFlutterBinding.ensureInitialized();
112	
113	  const secureStorageChannel = MethodChannel(
114	    'plugins.it_nomads.com/flutter_secure_storage',
115	  );
116	  final fakeNativeStorage = <String, String>{};
117	
118	  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
119	    final args = call.arguments as Map<dynamic, dynamic>;
120	    switch (call.method) {
121	      case 'write':
122	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
123	        return null;
124	      case 'read':
125	        return fakeNativeStorage[args['key'] as String];
126	      case 'delete':
127	        fakeNativeStorage.remove(args['key'] as String);
128	        return null;
129	      case 'containsKey':
130	        return fakeNativeStorage.containsKey(args['key'] as String);
131	      default:
132	        return null;
133	    }
134	  }
135	
136	  late FakePathProviderPlatform fakePathProvider;
137	  late _FakeHttpClientAdapter adapter;
138	
