94	  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
95	    final args = call.arguments as Map<dynamic, dynamic>;
96	    switch (call.method) {
97	      case 'write':
98	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
99	        return null;
100	      case 'read':
101	        return fakeNativeStorage[args['key'] as String];
102	      case 'delete':
103	        fakeNativeStorage.remove(args['key'] as String);
104	        return null;
105	      case 'containsKey':
106	        return fakeNativeStorage.containsKey(args['key'] as String);
107	      default:
108	        return null;
109	    }
110	  }
