131	/// Opens the real `InsertionModal` from a minimal host screen with an
132	/// "open" button — `InsertionModal.show` just needs a `BuildContext` with
133	/// a `Navigator` ancestor, same as `showModalBottomSheet` itself.
134	Future<void> _openModal(
135	  WidgetTester tester,
136	  TextEntryCubit cubit, {
137	  bool disableAnimations = false,
138	}) async {
139	  // Only `cubit` is scripted per test (`fakeRepository.nextResult`/`gate`)
140	  // — none of this file's tests ever switch to the Áudio/Foto tabs to do
141	  // anything beyond proving they render, so a fresh, never-configured
142	  // `AudioEntryCubit`/`PhotoEntryCubit` (backed by the trivial "not
143	  // expected to be called" fakes above) is always enough here.
144	  final audioCubit = AudioEntryCubit(
145	    _FakeMicRecorder(),
146	    _FakeAudioTranscriber(),
147	    _FakeEntriesRepository(),
148	  );
149	  final photoCubit = PhotoEntryCubit(
150	    _FakePhotoPicker(),
151	    _FakeMediaRepository(),
152	    _FakeEntriesRepository(),
153	  );
154	  await tester.pumpWidget(
155	    // Review finding: a bare `MediaQueryData(disableAnimations: ...)`
156	    // (rather than `.copyWith` over the ambient one) defaults every
157	    // other field to zero — `viewInsets` included — permanently
158	    // shadowing the real one from `tester.view`, so a test that sets
159	    // `tester.view.viewInsets` to simulate an open keyboard never
160	    // actually sees it reach the widget under test.
161	    Builder(
162	      builder: (outerContext) => MediaQuery(
163	        data: MediaQuery.of(outerContext)
164	            .copyWith(disableAnimations: disableAnimations),
165	        child: MaterialApp(
166	          home: Scaffold(
167	            body: Builder(
168	              builder: (context) => ElevatedButton(
169	                onPressed: () => InsertionModal.show(
170	                  context,
171	                  cubit: cubit,
172	                  audioCubit: audioCubit,
173	                  photoCubit: photoCubit,
174	                ),
175	                child: const Text('open'),
176	              ),
177	            ),
178	          ),
179	        ),
180	      ),
181	    ),
182	  );
183	  await tester.tap(find.text('open'));
184	}
