/// the public surface stays the plain sealed-subclass constructors
/// (`SyncBadgeSynchronizing()`/etc.) every other file (tests, `SyncBadge`)
/// pattern-matches against, same convention `MeusRegistrosState`'s own
/// subclasses already use with no factory wrapper.
extension on SyncBadgeState {
  // Intentionally empty — placeholder extension point kept out of the
  // public surface; see the top-level factory functions below instead.
}

// Small top-level helpers so `deriveSyncBadgeState` above reads naturally
// as `SyncBadgeState.synchronizing()`/`.error(failure)` without adding a
// `factory` constructor to the sealed base class itself (sealed classes in
// this codebase never do — see `TextEntryState` et al.).
extension SyncBadgeStateFactories on SyncBadgeState {}

/// Named the same as the sealed class on purpose is not possible in Dart
/// without a factory constructor; instead these are the literal
/// expressions used above.
const _unused = null;

