7	import 'package:fpdart/fpdart.dart';
8	
9	import '../../../../core/failure/failure.dart';
10	import '../entities/entry.dart';
11	import '../entities/pending_entry_write.dart';
12	import '../repositories/entries_repository.dart';
13	
14	/// The single `create()`/`retry()` entry point for all three capture
15	/// cubits (`TextEntryCubit`/`AudioEntryCubit`/`PhotoEntryCubit`) — Intent:
16	/// "the tracker, not `MeusRegistrosCubit`, owns reconciliation". Pure
17	/// Dart, no `package:flutter`/`data` import (RNF06) — a port+impl pair in
18	/// one file, same structural convention `SessionExpiryNotifier`/
19	/// `SessionExpiryNotifierImpl` already use.
20	abstract class PendingEntryWriteTracker {
21	  /// Identical contract to [EntriesRepository.create] (Boundaries) — every
22	  /// capture cubit swaps its `EntriesRepository` dependency for this one,
23	  /// with no other call-site change. Internally: records an optimistic
24	  /// [PendingEntryWrite] (status [PendingEntryWriteInFlight]) *before*
25	  /// calling through to the repository, so [pendingWrites] reflects it
26	  /// immediately; on success, drops the record and emits the confirmed
27	  /// [Entry] on [confirmedWrites]; on failure, flips the record to
28	  /// [PendingEntryWriteFailed] and leaves it for [retry].
29	  Future<Either<Failure, Entry>> create({
30	    required String content,
31	    required EntrySource source,
32	    int? mediaDurationSeconds,
33	  });
34	
35	  /// Replays the exact same payload a failed write ([tempId]) was created
36	  /// with (Never: "a second retry endpoint — retry replays `create()`
37	  /// verbatim"). A no-op for an unknown [tempId] or one that isn't
38	  /// currently [PendingEntryWriteFailed] (e.g. already in flight, or
39	  /// already resolved).
40	  Future<void> retry(String tempId);
41	
42	  /// Every write this tracker currently holds (in flight or failed) —
43	  /// `MeusRegistrosCubit` overlays this on its own confirmed list (Intent).
44	  /// Replay-capable: a late subscriber sees the current snapshot
45	  /// immediately rather than only future changes (`Stream.multi` + cached
46	  /// last value, mirrors `SessionRepositoryImpl.statusStream`,
47	  /// `session_repository_impl.dart:69-89`) — necessary here because
48	  /// `MeusRegistrosCubit` is a long-lived singleton that may subscribe
49	  /// well after a write is already pending (e.g. the user opens "Meus
50	  /// Registros" after already starting a save from Home).
51	  Stream<List<PendingEntryWrite>> get pendingWrites;
52	
53	  /// Broadcasts the real, server-confirmed [Entry] the instant a
54	  /// [create]/[retry] call resolves successfully — the one channel
55	  /// `MeusRegistrosCubit` (which never calls [create]/[retry] itself, and
56	  /// never talks to a capture cubit directly, AD-7) has to learn of a
57	  /// just-confirmed write and prepend it into its own state (Boundaries:
58	  /// "tracker drops the record; `MeusRegistrosCubit` prepends the
59	  /// confirmed `Entry` into its own state"). No replay semantics, same
60	  /// rationale `SessionExpiryNotifier.expiredEvents` already documents: a
61	  /// one-shot signal per confirmation, not a value a late subscriber needs
62	  /// to catch up on — a write that confirmed before `MeusRegistrosCubit`
63	  /// ever subscribed will simply arrive through its next `list()`
64	  /// instead.
65	  Stream<Entry> get confirmedWrites;
66	}
67	
68	/// Default implementation — an in-memory `Map` of outstanding writes
69	/// (Never: "persisting pending writes" — nothing here ever touches disk;
70	/// a killed app loses every pending record, by design, UX-DR30).
71	class PendingEntryWriteTrackerImpl implements PendingEntryWriteTracker {
72	  PendingEntryWriteTrackerImpl({required EntriesRepository repository})
73	    : _repository = repository;
74	
75	  final EntriesRepository _repository;
76	
77	  /// Insertion order matters for display (Boundaries: "Card appears
78	  /// top-of-today... before server responds") — a `Map` preserves it in
79	  /// Dart, and lookups by [PendingEntryWrite.tempId] (for [retry]) stay
80	  /// O(1).
81	  final Map<String, PendingEntryWrite> _pending = {};
82	
83	  final StreamController<List<PendingEntryWrite>> _pendingController =
84	      StreamController<List<PendingEntryWrite>>.broadcast();
85	
86	  final StreamController<Entry> _confirmedController =
87	      StreamController<Entry>.broadcast();
88	
89	  /// Monotonic suffix so two `create()` calls landing in the very same
90	  /// microtask (e.g. two fast capture saves) never collide on
91	  /// [DateTime.now]'s own millisecond resolution.
92	  int _nextSuffix = 0;
93	
94	  List<PendingEntryWrite> get _snapshot => List.unmodifiable(_pending.values);
95	
96	  @override
97	  Stream<List<PendingEntryWrite>> get pendingWrites {
98	    // Mirrors `SessionRepositoryImpl.statusStream` exactly: a fresh
99	    // listener gets the current snapshot synchronously, then every
100	    // further change the shared broadcast controller delivers.
101	    return Stream<List<PendingEntryWrite>>.multi((controller) {
102	      controller.add(_snapshot);
103	      final subscription = _pendingController.stream.listen(
104	        controller.add,
105	        onError: controller.addError,
106	        onDone: controller.close,
107	      );
108	      controller.onCancel = subscription.cancel;
109	    }, isBroadcast: true);
110	  }
111	
112	  @override
113	  Stream<Entry> get confirmedWrites => _confirmedController.stream;
114	
115	  void _emitPending() {
116	    if (_pendingController.isClosed) {
117	      return;
118	    }
119	    _pendingController.add(_snapshot);
120	  }
121	
122	  String _generateTempId() =>
123	      'pending-${DateTime.now().microsecondsSinceEpoch}-${_nextSuffix++}';
124	
125	  @override
126	  Future<Either<Failure, Entry>> create({
127	    required String content,
128	    required EntrySource source,
129	    int? mediaDurationSeconds,
130	  }) async {
131	    final tempId = _generateTempId();
132	    _pending[tempId] = PendingEntryWrite(
133	      tempId: tempId,
134	      content: content,
135	      source: source,
136	      mediaDurationSeconds: mediaDurationSeconds,
137	      startedAt: DateTime.now(),
138	      status: const PendingEntryWriteInFlight(),
139	    );
140	    _emitPending();
141	
142	    final result = await _repository.create(
143	      content: content,
144	      source: source,
145	      mediaDurationSeconds: mediaDurationSeconds,
146	    );
147	    _resolve(tempId, result);
148	    return result;
149	  }
150	
151	  @override
152	  Future<void> retry(String tempId) async {
153	    final current = _pending[tempId];
154	    if (current == null || current.status is! PendingEntryWriteFailed) {
155	      // Unknown, already in flight, or already resolved — I/O matrix's
156	      // "Write fails, non-retryable" row also routes through this guard
157	      // indirectly: `SyncBadge` only ever calls [retry] for a
158	      // `Failure.retryable` error in the first place, but this stays the
159	      // authoritative check regardless of how `retry()` is invoked.
160	      return;
161	    }
162	    _pending[tempId] = current.copyWith(status: const PendingEntryWriteInFlight());
163	    _emitPending();
164	
165	    final result = await _repository.create(
166	      content: current.content,
167	      source: current.source,
168	      mediaDurationSeconds: current.mediaDurationSeconds,
169	    );
170	    _resolve(tempId, result);
171	  }
172	
173	  /// Shared success/failure handling for both [create] and [retry] — on
174	  /// success, drops the pending record and broadcasts the confirmed
175	  /// [Entry]; on failure, flips the record to [PendingEntryWriteFailed]
176	  /// (re-reads [_pending] rather than trusting a closed-over reference, in
177	  /// case a concurrent call already replaced it).
178	  void _resolve(String tempId, Either<Failure, Entry> result) {
179	    result.match(
180	      (failure) {
181	        final latest = _pending[tempId];
182	        if (latest == null) {
183	          return;
184	        }
185	        _pending[tempId] = latest.copyWith(
186	          status: PendingEntryWriteFailed(failure: failure),
187	        );
188	        _emitPending();
189	      },
190	      (entry) {
191	        _pending.remove(tempId);
192	        _emitPending();
193	        if (!_confirmedController.isClosed) {
194	          _confirmedController.add(entry);
195	        }
196	      },
197	    );
198	  }
199	}
