1	import 'dart:async';
2	
3	import 'package:flutter_bloc/flutter_bloc.dart';
4	
5	import '../../domain/entities/entry.dart';
6	import '../../domain/entities/pending_entry_write.dart';
7	import '../../domain/repositories/entries_repository.dart';
8	import '../../domain/services/pending_entry_write_tracker.dart';
9	import 'meus_registros_state.dart';
10	
11	/// Drives `MeusRegistrosScreen` — calls `EntriesRepository.list()` directly
12	/// (no use-case layer, matching this codebase's existing small-scope
13	/// convention: `AccountSettingsCubit`/`AuthCubit`/`TextEntryCubit`). A
14	/// `lazySingleton` (Code Map), like `AccountSettingsCubit` — long-lived, so
15	/// the already-fetched pages survive leaving and re-entering
16	/// `/meus-registros` within the same app session.
17	///
18	/// spec-4-2 — also subscribes to [PendingEntryWriteTracker.pendingWrites]/
19	/// `.confirmedWrites` for this cubit's whole lifetime (constructor-wired,
20	/// not `loadFirstPage()`-wired): both streams are shared singleton
21	/// broadcasts a capture cubit on a *different* screen can drive at any
22	/// time, and this cubit is itself a long-lived singleton that must reflect
23	/// them regardless of which screen is currently visible.
24	class MeusRegistrosCubit extends Cubit<MeusRegistrosState> {
25	  MeusRegistrosCubit(this._repository, this._tracker)
26	    : super(const MeusRegistrosLoading()) {
27	    _pendingSubscription = _tracker.pendingWrites.listen(
28	      _onPendingWritesChanged,
29	    );
30	    _confirmedSubscription = _tracker.confirmedWrites.listen(
31	      _onEntryConfirmed,
32	    );
33	  }
34	
35	  final EntriesRepository _repository;
36	  final PendingEntryWriteTracker _tracker;
37	  late final StreamSubscription<List<PendingEntryWrite>> _pendingSubscription;
38	  late final StreamSubscription<Entry> _confirmedSubscription;
39	
40	  /// Mirrors the tracker's own latest snapshot regardless of [state]'s
41	  /// current type — so a pending write that arrives while [state] is
42	  /// still [MeusRegistrosLoading]/[MeusRegistrosError] isn't lost: the
43	  /// next [loadFirstPage] that resolves into [MeusRegistrosLoaded]/
44	  /// [MeusRegistrosEmpty] seeds itself from this field directly.
45	  List<PendingEntryWrite> _pendingWrites = const [];
46	
47	  /// A monotonic counter guarding against a stale in-flight call's result
48	  /// landing after a newer call has already changed the state (e.g. the
49	  /// user leaves and quickly re-enters `/meus-registros` while a slow
50	  /// first request is still pending, or taps retry before the original
51	  /// request resolves). Incremented at the start of every [loadFirstPage],
52	  /// then captured locally before each `await` in [loadFirstPage]/
53	  /// [_fetchMore] — a result whose captured generation no longer matches
54	  /// this counter by the time it resolves is discarded rather than
55	  /// emitted.
56	  int _generation = 0;
57	
58	  void _onPendingWritesChanged(List<PendingEntryWrite> pendingWrites) {
59	    _pendingWrites = pendingWrites;
60	    final current = state;
61	    if (current is MeusRegistrosLoaded) {
62	      emit(current.copyWith(pendingWrites: pendingWrites));
63	    } else if (current is MeusRegistrosEmpty && pendingWrites.isNotEmpty) {
64	      // A capture save starts while this screen is showing "no entries
65	      // yet" — the pending write's own placeholder card must still show
66	      // immediately (Acceptance Criteria), not wait for a reload.
67	      emit(
68	        MeusRegistrosLoaded(
69	          entries: const [],
70	          nextCursor: null,
71	          pendingWrites: pendingWrites,
72	        ),
73	      );
74	    }
75	    // MeusRegistrosLoading/MeusRegistrosError: nothing to overlay onto yet
76	    // — [_pendingWrites] above already keeps the latest snapshot, which
77	    // the next loadFirstPage() resolution reads directly.
78	  }
79	
80	  void _onEntryConfirmed(Entry entry) {
81	    final current = state;
82	    if (current is MeusRegistrosLoaded) {
83	      // Prepended, not reloaded (Design Notes) — preserves this cubit's
84	      // own pagination state (`nextCursor`/`loadMoreFailed`) exactly as
85	      // `loadMore()`'s own cursor-overlap robustness already relies on;
86	      // `_dedupedById` (unchanged) absorbs the degenerate case where a
87	      // later `list()`/`loadMore()` page's cursor also happens to repeat
88	      // this same (now server-known) id.
89	      emit(current.copyWith(entries: _dedupedById([entry, ...current.entries])));
90	    } else if (current is MeusRegistrosEmpty) {
91	      emit(
92	        MeusRegistrosLoaded(
93	          entries: [entry],
94	          nextCursor: null,
95	          pendingWrites: _pendingWrites,
96	        ),
97	      );
98	    }
99	    // MeusRegistrosLoading/MeusRegistrosError: the next loadFirstPage()
100	    // fetches the server's own fresh page, which already includes this
101	    // entry now that it's confirmed server-side — nothing to reconcile.
102	  }
103	
104	  /// `EntryRecordCard`'s own retry tap (`MeusRegistrosScreen`) — forwards
105	  /// to the shared tracker verbatim (Never: "a second retry endpoint").
106	  Future<void> retry(String tempId) => _tracker.retry(tempId);
107	
108	  /// `MeusRegistrosScreen.initState` calls this once, every mount — always
109	  /// re-fetches from scratch rather than keeping a previous visit's page
110	  /// around, since a new entry may have been saved (Insertion Modal, Epic
111	  /// 3) since the last visit.
112	  Future<void> loadFirstPage() async {
113	    final generation = ++_generation;
114	    emit(const MeusRegistrosLoading());
115	    final result = await _repository.list();
116	    // Mirrors `AccountSettingsCubit.toggleBiometric`'s own guard: `close()`
117	    // can race this awaited call (e.g. a fast app teardown mid-request) —
118	    // `emit()` after `close()` would otherwise throw.
119	    if (isClosed || generation != _generation) {
120	      return;
121	    }
122	    result.match(
123	      (failure) => emit(MeusRegistrosError(message: failure.message)),
124	      (page) {
125	        // Same degenerate-cursor distrust as `_fetchMore`'s own guard below:
126	        // a page reporting zero items is treated as exhausted regardless of
127	        // `page.nextCursor` — an empty first page with a non-null cursor
128	        // would otherwise strand the user on `MeusRegistrosEmpty` with no
129	        // way back to a cursor this state no longer tracks. spec-4-2: also
130	        // skipped whenever a pending write is already outstanding — its
131	        // own placeholder card still needs to show.
132	        if (page.items.isEmpty && _pendingWrites.isEmpty) {
133	          emit(const MeusRegistrosEmpty());
134	          return;
135	        }
136	        emit(
137	          MeusRegistrosLoaded(
138	            entries: _dedupedById(page.items),
139	            nextCursor: page.nextCursor,
140	            pendingWrites: _pendingWrites,
141	          ),
142	        );
143	      },
144	    );
145	  }
146	
147	  /// `MeusRegistrosScreen`'s scroll listener calls this near the list's
148	  /// end. A no-op while not [MeusRegistrosLoaded], while
149	  /// [MeusRegistrosLoaded.nextCursor] is already `null`, while a call is
150	  /// already in flight, or — critically — once
151	  /// [MeusRegistrosLoaded.loadMoreFailed] is already `true`: without that
152	  /// last guard, a failed page's own footer swapping from a spinner to a
153	  /// "Tentar novamente" button can shift the list's `maxScrollExtent`
154	  /// just enough to leave the scroll position still inside the
155	  /// pre-fetch-buffer zone, re-firing this same listener and retrying
156	  /// forever — observed directly as an unbounded `pumpAndSettle` loop in
157	  /// this screen's own widget test. Once failed, only an explicit
158	  /// [retryLoadMore] (the footer's own button) tries again.
159	  Future<void> loadMore() => _fetchMore(isRetry: false);
160	
161	  /// The footer's "Tentar novamente" button — the one path allowed to
162	  /// retry past a [MeusRegistrosLoaded.loadMoreFailed] of `true`
163	  /// ([loadMore]'s own doc).
164	  Future<void> retryLoadMore() => _fetchMore(isRetry: true);
165	
166	  Future<void> _fetchMore({required bool isRetry}) async {
167	    final current = state;
168	    if (current is! MeusRegistrosLoaded ||
169	        current.nextCursor == null ||
170	        current.isLoadingMore ||
171	        (current.loadMoreFailed && !isRetry)) {
172	      return;
173	    }
174	    final generation = _generation;
175	    emit(current.copyWith(isLoadingMore: true, loadMoreFailed: false));
176	    final result = await _repository.list(cursor: current.nextCursor);
177	    if (isClosed || generation != _generation) {
178	      return;
179	    }
180	    // Re-reads `state` rather than closing over `current` — defensive
181	    // against `loadFirstPage()` having reset the state to something other
