227	/// [seenIds] accumulates as entries are walked.
228	List<Entry> _dedupedById(List<Entry> entries, {Set<String>? seenIds}) {
229	  final seen = seenIds ?? <String>{};
230	  return [
231	    for (final entry in entries)
